// Log summary of run outcomes
const items = $input.all();
const summary = items.map(item => ({
  run_id: item.json.run_id,
  bot_id: item.json.bot_id,
  status: item.json.status,
  processed: item.json.processed,
  published: item.json.published,
  errors: item.json.errors?.length || 0
}));
return [{ json: { timestamp: new Date().toISOString(), batch_summary: summary } }];
